/* Monta { fr, de, it } a partir de uma entrada dos mapas acima.
   Chave que não existe devolve objeto vazio, e o `?? obj.en` de quem chama
   faz o resto: o idioma recai no inglês em vez de aparecer vazio. */
export function idiomasDe(mapa, chave) {
  const v = mapa[chave];
  return v ? { fr: v[0], de: v[1], it: v[2] } : {};
}

